import { useEffect, useRef, useState } from "react";
import useVantaHalo from "./useVantaHalo";

export default function OngoingInterview() {
  const vantaRef = useVantaHalo();
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const [showPopup, setShowPopup] = useState(true);
  const [mediaError, setMediaError] = useState(null);

  const startMedia = async () => {
    setShowPopup(false);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: true,
        audio: true,
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      setMediaError("Could not access camera or microphone. Please check your permissions.");
    }
  };

  useEffect(() => {
    return () => {
      // Cleanup: stop all tracks when leaving the page
      if (streamRef.current) {
        streamRef.current.getTracks().forEach((track) => track.stop());
      }
    };
  }, []);

  return (
    <div ref={vantaRef} className="min-h-screen flex flex-col items-center justify-center px-6 py-16 text-center">

      {/* Recording alert popup */}
      {showPopup && (
        <div className="fixed inset-0 flex items-center justify-center z-50 bg-black/50">
          <div className="bg-white rounded-xl p-8 max-w-sm mx-4 shadow-xl text-left">
            <h2 className="text-lg font-semibold text-stone-900 mb-2">You are being recorded</h2>
            <p className="text-sm text-stone-600 leading-relaxed mb-6">
              This interview session will use your camera and microphone. By continuing, you consent to being recorded for the duration of the interview.
            </p>
            <button
              onClick={startMedia}
              className="w-full h-10 rounded-md text-sm font-medium bg-stone-900 text-white hover:bg-stone-800 transition-colors"
            >
              I understand, continue
            </button>
          </div>
        </div>
      )}

      <h1 className="text-3xl font-semibold text-white mb-6">Ongoing Interview</h1>

      {mediaError ? (
        <p className="text-red-400 text-sm">{mediaError}</p>
      ) : (
        <video
          ref={videoRef}
          autoPlay
          muted
          playsInline
          className="rounded-xl w-full max-w-md border border-white/20"
        />
      )}

      <p className="text-white/70 text-sm mt-4">
        Interview in progress. Content coming soon.
      </p>
    </div>
  );
}
